await page.goto('http://www.icse-conferences.org/reports.html');
await page.getByRole('link',{name:/duplicate submission/i}).first().click();
await page.evaluate(() => {const t=document.body.innerText;const s=t.split(/\n/).filter(x=>/agreed|\b(?:19|20)\d\d\b/i.test(x)).join(' ').trim();return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:'duplicate submission',values:[s],answer:s}})

await page.goto('http://www.icse-conferences.org/reports.html');
await page.evaluate(() => {const a=Array.from(document.links).find(a=>/duplicat|double.submi|multiple.submi/i.test(a.innerText+' '+a.href));if(a)a.click()});
await page.evaluate(() => {const t=document.body.innerText;const m=t.match(/[^
]*(?:agreed|adopted)[^
]*(?:
[^
]+)?/i)||t.match(/[^
]*duplicat[^
]*/i);const s=m?m[0].trim():t.slice(-1500);return {url:location.href,title:document.title,h1:document.querySelector('h1')?.innerText,key_text:s,values:[s],answer:s}})
